SELECT 


  AND d.gmt_create >= #{start} AND d.gmt_create < #{end}
  AND d.agent_id = #{agentId}
  AND d.agent_version_id = #{agentVersionId}
  AND d.status = #{status}

      AND EXISTS (SELECT 1 FROM squad_member sm JOIN squad sq ON sq.id = sm.squad_id AND sq.tenant_id = sm.tenant_id
                  WHERE sm.tenant_id = d.tenant_id AND sm.agent_id = d.agent_id AND sm.squad_id = #{squadId} AND sq.is_deleted = 0)

  AND COALESCE(snap.sdlc_id, entry.sdlc_id, av.sdlc_id) = #{sdlcId}
  AND d.id <= #{maxDispatchId}
ORDER BY d.gmt_create DESC, d.id DESC
LIMIT #{limit}

mapper.sql:

AND d.gmt_create >= #{start} AND d.gmt_create < #{end}
AND snap.id IS NULL
AND (bound.source IS NULL OR bound.source IN ('UNAVAILABLE', 'UNVERIFIED', 'RECOVERED'))
AND d.status IN ('SUCCEEDED', 'FAILED', 'TIMEOUT', 'CANCELED')
AND d.package_oss_ref IS NOT NULL AND TRIM(d.package_oss_ref) != ''
AND d.id < #{beforeDispatchId}

    AND EXISTS (SELECT 1 FROM squad_member sm JOIN squad sq ON sq.id = sm.squad_id AND sq.tenant_id = sm.tenant_id
                WHERE sm.tenant_id = d.tenant_id AND sm.agent_id = d.agent_id AND sm.squad_id = #{squadId} AND sq.is_deleted = 0)

AND COALESCE(snap.sdlc_id, entry.sdlc_id, av.sdlc_id) = #{sdlcId}

